int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct ctl_dir *dir_header;
    int result;

    dir_header = get_ctl_dir_header(file);
    if (!dir_header) {
        return -ENOENT;
    }

    if (dir_emit_dots(file, ctx)) {
        put_ctl_dir_header(dir_header);
        return -ENOMEM;
    }

    result = 0;
    while (dir_header && !result) {
        result = scan_ctl_dir_entries(dir_header, ctx);
        if (result < 0) {
            break;
        }
        dir_header = dir_header->next;
    }

    finish_ctl_dir_header_processing(dir_header);
    return 0;
}

int sysctl_file_readdir(struct file *file, struct dir_context *ctx) {
    struct sysctl_directory_header *header;
    int ret = 0;

    header = get_sysctl_directory_header(file);
    if (!header)
        return -ENOENT;

    if (dir_emit_dots(file, ctx))
        return -EINVAL;

    for (struct sysctl_entry *entry = header->entries; entry; entry = entry->next) {
        ret = scan_sysctl_entry(entry, file, ctx);
        if (ret < 0) {
            finish_sysctl_header(header);
            return ret;
        }
    }

    finish_sysctl_header(header);
    return 0;
}

