int sysctl_file_readdir(struct file *file, struct dir_context *ctx) {
    struct ctl_dir *dir_header;
    int ret = 0;

    dir_header = get_dir_header(file);
    if (!dir_header)
        return -ENOENT;

    if (dir_emit_dots(file, ctx))
        return 0;

    mutex_lock(&dir_header->lock);
    list_for_each_entry(struct ctl_entry *entry, &dir_header->ctl_entry_list, list) {
        ret = scan_ctl_entry(entry, file, ctx);
        if (ret)
            break;
    }
    mutex_unlock(&dir_header->lock);

    if (ret) {
        finish_dir_header(dir_header);
        return ret;
    }

    finish_dir_header(dir_header);
    return 0;
}

